/*
* This script compiles modules for evaluating rational functions
* used by the modified Bessel function of the second kind of order one (K1).
*
* If any coefficients change, this script should be rerun.
*/
'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var readFileSync = require( '@stdlib/fs/read-file' ).sync;
var writeFileSync = require( '@stdlib/fs/write-file' ).sync;
var currentYear = require( '@stdlib/time/current-year' );
var licenseHeader = require( '@stdlib/_tools/licenses/header' );
var compile = require( '@stdlib/math/base/tools/evalrational-compile' );
var compileC = require( '@stdlib/math/base/tools/evalrational-compile-c' );
var substringBefore = require( '@stdlib/string/substring-before' );
var substringAfter = require( '@stdlib/string/substring-after' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

// Small-x rational in a = x²/4 (Boost bessel_k1, 53-bit):
var P1 = [
	-3.62137953440350228e-03,
	7.11842087490330300e-03,
	1.00302560256614306e-05,
	1.77231085381040811e-06
];

var Q1 = [
	1.00000000000000000e+00,
	-4.80414794429043831e-02,
	9.85972641934416525e-04,
	-8.91196859397070326e-06
];

// Small-x rational in x² (Boost bessel_k1, 53-bit):
var P2 = [
	-3.07965757829206184e-01,
	-7.80929703673074907e-02,
	-2.70619343754051620e-03,
	-2.49549522229072008e-05
];

var Q2 = [
	1.00000000000000000e+00,
	-2.36316836412163098e-02,
	2.64524577525962719e-04,
	-1.49749618004162787e-06
];

// Large-x rational in 1/x (Boost bessel_k1, 53-bit):
var P3 = [
	-1.97028041029226295e-01,
	-2.32408961548087617e+00,
	-7.98269784507699938e+00,
	-2.39968410774221632e+00,
	3.28314043780858713e+01,
	5.67713761158496058e+01,
	3.30907788466509823e+01,
	6.62582288933739787e+00,
	3.08851840645286691e-01
];

var Q3 = [
	1.00000000000000000e+00,
	1.41811409298826118e+01,
	7.35979466317556420e+01,
	1.77821793937080859e+02,
	2.11014501598705982e+02,
	1.19425262951064454e+02,
	2.88448064302447607e+01,
	2.27912927104139732e+00,
	2.50358186953478678e-02
];

// Header to add to output files:
var header = licenseHeader( 'Apache-2.0', 'js', {
	'year': currentYear(),
	'copyright': 'The Stdlib Authors'
});
header += '\n/* This is a generated file. Do not edit directly. */\n';


// FUNCTIONS //

/**
* Inserts a string between two markers in a text.
*
* @private
* @param {string} text - input text
* @param {string} id - marker id
* @param {string} str - string to insert
* @returns {string} modified text
*/
function insert( text, id, str ) {
	var before;
	var after;

	before = substringBefore( text, '// BEGIN: '+id );
	after = substringAfter( text, '// END: '+id );

	return format( '%s// BEGIN: %s\n\n%s\n// END: %s%s', before, id, str, id, after );
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var fpath;
	var copts;
	var opts;
	var file;

	opts = {
		'encoding': 'utf8'
	};

	// JS evaluators:
	fpath = resolve( __dirname, '..', 'lib', 'rational_p1q1.js' );
	writeFileSync( fpath, header + compile( P1, Q1 ), opts );

	fpath = resolve( __dirname, '..', 'lib', 'rational_p2q2.js' );
	writeFileSync( fpath, header + compile( P2, Q2 ), opts );

	fpath = resolve( __dirname, '..', 'lib', 'rational_p3q3.js' );
	writeFileSync( fpath, header + compile( P3, Q3 ), opts );

	// C evaluators (for rational_small, rational_p2q2, rational_large in main.c):
	copts = {
		'dtype': 'double',
		'name': ''
	};
	fpath = resolve( __dirname, '..', 'src', 'main.c' );
	file = readFileSync( fpath, opts );

	copts.name = 'rational_p1q1';
	file = insert( file, copts.name, compileC( P1, Q1, copts ) );

	copts.name = 'rational_p2q2';
	file = insert( file, copts.name, compileC( P2, Q2, copts ) );

	copts.name = 'rational_p3q3';
	file = insert( file, copts.name, compileC( P3, Q3, copts ) );

	writeFileSync( fpath, file, opts );
}

main();
